import React, { createContext, useContext, useMemo } from 'react';
import { isLeadChatAutomationPaused } from '../utils/leadChatAutomation';
import { isComposerActive, isComposerLocked } from '../utils/leadChatComposerMode';

const LeadChatAutomationContext = createContext({
  isAutomationPaused: false,
  isHandlingSession: false,
  isViewOnlyIntervene: false,
});

export function LeadChatAutomationProvider({ composerMode, children }) {
  const value = useMemo(
    () => ({
      isAutomationPaused: isLeadChatAutomationPaused(composerMode),
      isHandlingSession: isComposerActive(composerMode),
      isViewOnlyIntervene: isComposerLocked(composerMode),
    }),
    [composerMode]
  );

  return (
    <LeadChatAutomationContext.Provider value={value}>
      {children}
    </LeadChatAutomationContext.Provider>
  );
}

export function useLeadChatAutomation() {
  return useContext(LeadChatAutomationContext);
}

export default LeadChatAutomationContext;
