const PLACEHOLDER_FILE_NAMES =
  /^(header\.(document|image|video|text|file)|\{\{\s*\d+\s*\}\}|document|file|media)$/i;

export function sanitizeLeadChatFileName(fileName, fallback = 'Document') {
  const trimmed = `${fileName || ''}`.trim();
  if (!trimmed || PLACEHOLDER_FILE_NAMES.test(trimmed)) {
    return fallback;
  }
  return trimmed;
}

export function formatLeadChatTemplateLabel(templateName) {
  if (!templateName) return 'Template';
  return `${templateName}`
    .replace(/_/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase()
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

export function isLeadChatRichMessageKind(kind) {
  return kind === 'template' || kind === 'buttons' || kind === 'list';
}
