import React, { useEffect, useMemo, useState } from 'react';
import { Box } from '@mui/material';
import InfiniteSearchableSelect from '../../../../components/ui/SearchableSelect/InfiniteSearchableSelect';
import SearchableSelect from '../../../../components/ui/SearchableSelect/SearchableSelect';
import { getFormControlSx } from '../../../../components/ui/Form/controls/formControlStyles';
import { useFeatureTheme } from '../../../../theme/hooks/useFeatureTheme';
import { fetchBotNumberListPage } from '../../../whatsapp-templates/adapters/botNumberListAdapter';
import { mapBotToSelectOption } from '../../../whatsapp-templates/utils/normalizeTemplate';
import { templateService } from '../../../whatsapp-templates/services/templateService';

const isSameBot = (a, b) =>
  (a?.wa_phone_number ?? a?.value) === (b?.wa_phone_number ?? b?.value);
const getBotId = (option) => option?.wa_phone_number ?? option?.value ?? option?.id ?? null;
const getBotLabel = (option) => option?.label ?? option?.wa_phone_number ?? '';
const isSameTemplate = (a, b) => (a?.name ?? a?.value) === (b?.name ?? b?.value);

function extractTemplateList(response) {
  const payload = response?.data ?? response;
  const list =
    payload?.results ??
    payload?.list ??
    payload?.data?.results ??
    payload?.data?.list ??
    (Array.isArray(payload) ? payload : []);
  return Array.isArray(list) ? list : [];
}

export default function LeadSendTemplateFieldSelects({
  organisationId,
  botNumber,
  botValue,
  selectedTemplateMeta,
  onBotChange,
  onTemplateChange,
  botLabel,
  templateLabel,
  disabled = false,
}) {
  const themeTokens = useFeatureTheme();
  const selectSx = useMemo(
    () => getFormControlSx(themeTokens),
    [themeTokens]
  );

  const [templateOptions, setTemplateOptions] = useState([]);
  const [isLoadingTemplates, setIsLoadingTemplates] = useState(false);

  useEffect(() => {
    if (!organisationId || !botNumber) {
      setTemplateOptions([]);
      return undefined;
    }

    let cancelled = false;
    setIsLoadingTemplates(true);

    templateService
      .getAllTemplates({ organisation_id: organisationId, bot_number: botNumber })
      .then((res) => {
        if (cancelled) return;
        const approved = extractTemplateList(res).filter(
          (item) => String(item?.status ?? '').toUpperCase() === 'APPROVED'
        );
        setTemplateOptions(
          approved.map((item) => ({
            ...item,
            label: item.name,
            value: item.name,
          }))
        );
      })
      .catch(() => {
        if (!cancelled) setTemplateOptions([]);
      })
      .finally(() => {
        if (!cancelled) setIsLoadingTemplates(false);
      });

    return () => {
      cancelled = true;
    };
  }, [botNumber, organisationId]);

  return (
    <Box
      sx={{
        display: 'grid',
        gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' },
        gap: 2,
      }}
    >
      <InfiniteSearchableSelect
        label={botLabel}
        placeholder={botLabel}
        extraParams={{ organisation_id: organisationId }}
        fetchPage={fetchBotNumberListPage}
        pageSize={20}
        enabled={Boolean(organisationId)}
        loadOnOpen
        valueId={botNumber || null}
        selectedSeed={botValue}
        mapToOption={mapBotToSelectOption}
        isSameOption={isSameBot}
        getOptionId={getBotId}
        getOptionLabel={getBotLabel}
        isOptionEqualToValue={isSameBot}
        onChange={onBotChange}
        SelectComponent={SearchableSelect}
        noOptionsText="No bot numbers found"
        disabled={disabled || !organisationId}
        sx={selectSx}
        shrinkLabel
      />

      <SearchableSelect
        label={templateLabel}
        placeholder={templateLabel}
        options={templateOptions}
        value={selectedTemplateMeta}
        onChange={onTemplateChange}
        labelKey="label"
        valueKey="name"
        getOptionLabel={(option) => option?.name ?? option?.label ?? ''}
        isOptionEqualToValue={isSameTemplate}
        loading={isLoadingTemplates}
        disabled={disabled || !botNumber}
        noOptionsText={botNumber ? 'No approved templates found' : 'Select a bot number first'}
        sx={selectSx}
        shrinkLabel
      />
    </Box>
  );
}
