import { getLeadFieldValue } from '../../adapters/tableRecordsAdapter';

const PHONE_REGEX = /^([1-9]{1}[0-9]{1,12})$/;

export function normalizeLeadPhone(value) {
  if (value == null || value === '') {
    return { valid: false, normalized: '', error: 'Phone number is missing' };
  }

  let raw = String(value).trim().replace(/\s/g, '');
  if (!raw) {
    return { valid: false, normalized: '', error: 'Phone number is missing' };
  }
  if (!/^\d+$/.test(raw)) {
    return { valid: false, normalized: raw, error: `Invalid phone number "${raw}"` };
  }
  if (raw.length === 10) {
    raw = `91${raw}`;
  }
  if (!PHONE_REGEX.test(raw) || raw.length < 10) {
    return {
      valid: false,
      normalized: raw,
      error: `Invalid phone number "${raw}" (need 10 digits or country code)`,
    };
  }
  return { valid: true, normalized: raw, error: null };
}

export function resolveLeadPhoneFromRow(row) {
  const candidates = [
    row?.phone_number,
    row?._rawLead?.phone_number,
    getLeadFieldValue(row?._rawLead, 'phone_number'),
  ];
  for (const candidate of candidates) {
    const result = normalizeLeadPhone(candidate);
    if (result.valid) return result;
  }
  const last = normalizeLeadPhone(candidates.find((c) => c != null && c !== '') ?? '');
  return last;
}

export function resolveDefaultBotNumber(formPayload) {
  if (!formPayload || typeof formPayload !== 'object') return '';

  const notificationBot = formPayload.notification_config?.bot_number;
  if (notificationBot) return String(notificationBot);

  const interveneBot = formPayload.intervene_config?.bot_number;
  if (interveneBot) return String(interveneBot);

  return '';
}

export function summarizeRecipients(selectedRows = []) {
  const total = selectedRows.length;
  let withPhone = 0;

  selectedRows.forEach((row) => {
    if (resolveLeadPhoneFromRow(row).valid) {
      withPhone += 1;
    }
  });

  return {
    total,
    withPhone,
    withoutPhone: total - withPhone,
  };
}

export function buildRecipientSubtitle(selectedRows, copy) {
  const summary = summarizeRecipients(selectedRows);
  if (summary.total === 1) {
    const row = selectedRows[0];
    const phone = resolveLeadPhoneFromRow(row);
    const leadId = row?.lead_id ?? row?.id ?? '';
    const name =
      row?.customer_name
      ?? getLeadFieldValue(row?._rawLead, 'customer_name')
      ?? '';
    const phoneLabel = phone.valid ? phone.normalized : copy.noPhone;
    return copy.subtitleSingle(leadId, name, phoneLabel);
  }
  return copy.subtitleMulti(summary.total, summary.withPhone, summary.withoutPhone);
}

export { UPLOAD_SHEET_IGNORED_COLUMNS as ERROR_SHEET_META_COLUMNS, stripUploadSheetColumns as stripErrorSheetMetaColumns } from '../../../whatsapp-templates/utils/bulkSheetValidation';
